#include <bits/stdc++.h>
using namespace std;

long long large_INF = 1e18;
long long total_result = 0;
vector<int> memo_table;

int compute_min_moves(long long n) {
    if (n == 0) return 0;
    if (n < (long long)memo_table.size() && memo_table[n]) return memo_table[n];

    long long min_difference = large_INF;
    long long val = 1;
    int move_count=0;

    while (abs(val - n) <= min_difference) {
        min_difference = abs(val - n);
        val = val * 10 + 1;
        move_count++;
    }
    val /= 10;

    if (val > n && val / 10) {
        if (n < (long long)memo_table.size()) {
            return memo_table[n] = min(move_count + compute_min_moves(abs(val - n)),
                                         move_count - 1 + compute_min_moves(abs(val/10 - n)));
        }
        return min(move_count + compute_min_moves(abs(val - n)),
                   move_count - 1 + compute_min_moves(abs(val/10 - n)));
    }
    if (n < (long long)memo_table.size()) {
        return memo_table[n] = move_count + compute_min_moves(abs(val - n));
    }
    return move_count + compute_min_moves(abs(val - n));
}

int main() {
    ios_base::sync_with_stdio(false);
    long long n; cin >> n;
    memo_table.resize(1e7);
    cout << compute_min_moves(n);
    return 0;
}
